export const getRegistrationUpdateUrl = (registration: number) => {
  return `/registrations/${registration}`;
};

/**
 * Requires `registrations.manage`. Guests cannot amend their own
 * booking, so this is how a misspelled name, a wrong number or a
 * seating change is fixed.
 *
 * Send only the fields that change. An explicit `null` clears an
 * optional field; an omitted field is left alone.
 *
 * What was ordered cannot be changed here. Cancel the booking and make
 * a new one instead.
 * @summary Correct a booking's details
 */
export const registrationUpdate = async (
  registration: number,
  updateRegistrationRequest?: UpdateRegistrationRequest,
  options?: Parameters<typeof customFetch>[1],
): Promise<registrationUpdateResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<registrationUpdateResponse>(getRegistrationUpdateUrl(registration), {
    ...options,
    method: "PATCH",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(updateRegistrationRequest),
  });
};

